#define SOURCE_REST_PLAN_FIXTURE_ONLY
#include "source-rest-plan.cpp"
#include "cgltf.h"
#include "dome/vrm.hpp"
#include <bit>
namespace {
Vec3 transform(const float *m,Vec3 p){return {m[0]*p.x+m[4]*p.y+m[8]*p.z+m[12],m[1]*p.x+m[5]*p.y+m[9]*p.z+m[13],m[2]*p.x+m[6]*p.y+m[10]*p.z+m[14]};}
Vec3 consume(cgltf_node &node,size_t vertex){auto &primitive=node.mesh->primitives[0];float q[4]{};if(!cgltf_accessor_read_float(cgltf_find_accessor(&primitive,cgltf_attribute_type_position,0),vertex,q,3))throw std::runtime_error("Independent POSITION read failed");Vec3 position{q[0],q[1],q[2]};for(size_t target=0;target<primitive.targets_count;++target){const auto weight=target<node.weights_count?node.weights[target]:target<node.mesh->weights_count?node.mesh->weights[target]:0;for(size_t a=0;a<primitive.targets[target].attributes_count;++a)if(primitive.targets[target].attributes[a].type==cgltf_attribute_type_position){if(!cgltf_accessor_read_float(primitive.targets[target].attributes[a].data,vertex,q,3))throw std::runtime_error("Independent morph read failed");position+=Vec3{q[0],q[1],q[2]}*weight;}}
 if(!node.skin){float world[16];cgltf_node_transform_world(&node,world);return transform(world,position);}Vec3 result{};float sum=0;for(int set=0;;++set){const auto *joints=cgltf_find_accessor(&primitive,cgltf_attribute_type_joints,set),*weights=cgltf_find_accessor(&primitive,cgltf_attribute_type_weights,set);if(!joints&&!weights)break;if(!joints||!weights)throw std::runtime_error("Unpaired independent skin stream");float js[4],ws[4];if(!cgltf_accessor_read_float(joints,vertex,js,4)||!cgltf_accessor_read_float(weights,vertex,ws,4))throw std::runtime_error("Independent skin read failed");for(size_t k=0;k<4;++k)if(ws[k]){if(js[k]<0||js[k]>=node.skin->joints_count)throw std::runtime_error("Independent skin joint out of range");float world[16],bind[16];cgltf_node_transform_world(node.skin->joints[size_t(js[k])],world);if(!node.skin->inverse_bind_matrices||!cgltf_accessor_read_float(node.skin->inverse_bind_matrices,size_t(js[k]),bind,16))throw std::runtime_error("Independent explicit IBM missing");result+=transform(world,transform(bind,position))*ws[k];sum+=ws[k];}}
 if(std::abs(sum-1)>1e-5)throw std::runtime_error("Independent exported weight sum differs");return result;
}

using D=std::array<double,16>;
D dmatrix(const RigMatrix&m){D r{};for(size_t i=0;i<16;++i)r[i]=m[i];return r;}
D product(const D&a,const D&b){D r{};for(size_t c=0;c<4;++c)for(size_t y=0;y<4;++y)for(size_t k=0;k<4;++k)r[c*4+y]+=a[k*4+y]*b[c*4+k];return r;}
D inverse(D a){double rows[4][8]{};for(size_t r=0;r<4;++r)for(size_t c=0;c<4;++c){rows[r][c]=a[c*4+r];rows[r][c+4]=r==c;}for(size_t k=0;k<4;++k){size_t pivot=k;for(size_t r=k+1;r<4;++r)if(std::abs(rows[r][k])>std::abs(rows[pivot][k]))pivot=r;if(std::abs(rows[pivot][k])<1e-15)throw std::runtime_error("Independent inverse singular");for(size_t c=0;c<8;++c)std::swap(rows[k][c],rows[pivot][c]);auto scale=rows[k][k];for(size_t c=0;c<8;++c)rows[k][c]/=scale;for(size_t r=0;r<4;++r)if(r!=k){auto f=rows[r][k];for(size_t c=0;c<8;++c)rows[r][c]-=f*rows[k][c];}}D out{};for(size_t r=0;r<4;++r)for(size_t c=0;c<4;++c)out[c*4+r]=rows[r][c+4];return out;}
D node_world(const cgltf_node&n){float f[16];cgltf_node_transform_world(&n,f);D out{};for(size_t i=0;i<16;++i)out[i]=f[i];return out;}
Vec3 point(D m,Vec3 p){return {float(m[0]*p.x+m[4]*p.y+m[8]*p.z+m[12]),float(m[1]*p.x+m[5]*p.y+m[9]*p.z+m[13]),float(m[2]*p.x+m[6]*p.y+m[10]*p.z+m[14])};}
Vec3 unity_point(const nlohmann::json&j){return {j.at("x").get<float>(),j.at("y").get<float>(),-j.at("z").get<float>()};}
void near(Vec3 a,Vec3 b){if(length(a-b)>2e-5)throw std::runtime_error("Independent native VRM metadata world mismatch");}
void near(D a,D b){for(size_t k=0;k<16;++k)if(std::abs(a[k]-b[k])>2e-5)throw std::runtime_error("Independent native VRM metadata basis mismatch");}
void verify_vrm(const Scene&scene,uint64_t selected,const std::filesystem::path&file){
 const auto before=scene.encode();const auto graph=detail::capture_source_rest_graph(scene,selected);const auto pose=detail::source_rest_pose(graph);auto surfaces=scene.surfaces();const auto rawJson=nlohmann::json::parse(*surfaces.front().appearance->vrm_json);const auto &original=rawJson.contains("extensions")?rawJson.at("extensions").at("VRM"):rawJson;
 export_vrm(surfaces,file);cgltf_options options{};cgltf_data*raw=nullptr;if(cgltf_parse_file(&options,file.c_str(),&raw)!=cgltf_result_success)throw std::runtime_error("Independent VRM parse failed");std::unique_ptr<cgltf_data,decltype(&cgltf_free)> owner(raw,cgltf_free);check(cgltf_load_buffers(&options,raw,file.c_str())==cgltf_result_success&&cgltf_validate(raw)==cgltf_result_success,"Independent cgltf validates every fitted VRM accessor and graph");auto document=nlohmann::json::parse(raw->json,raw->json+raw->json_size);const auto &vrm=document.at("extensions").at("VRM");
 size_t skins=0,rigid=0,corners=0;double maximum=0;
 for(size_t n=0;n<raw->nodes_count;++n){auto &node=raw->nodes[n];if(!node.mesh)continue;auto part=size_t(node.mesh-raw->meshes);const auto &surface=surfaces.at(part);const auto &primitive=node.mesh->primitives[0];auto mesh=surface.preview_mesh();auto world=surface.world_matrix();if(node.skin){++skins;const auto binds=surface.deformation->skeleton->inverse_bind();if(node.skin->joints_count!=binds.size())throw std::runtime_error("Own skin slot count lost");for(size_t slot=0;slot<binds.size();++slot){float matrix[16];if(!cgltf_accessor_read_float(node.skin->inverse_bind_matrices,slot,matrix,16))throw std::runtime_error("Independent IBM read failed");for(size_t k=0;k<16;++k)if(std::bit_cast<uint32_t>(matrix[k])!=std::bit_cast<uint32_t>(binds[slot][k]))throw std::runtime_error("Per-part current IBM float bits changed part="+std::to_string(part)+" slot="+std::to_string(slot)+" column-entry="+std::to_string(k)+" actual="+std::to_string(matrix[k])+" bits="+std::to_string(std::bit_cast<uint32_t>(matrix[k]))+" expected="+std::to_string(binds[slot][k])+" bits="+std::to_string(std::bit_cast<uint32_t>(binds[slot][k])));}}else{++rigid;if(surface.deformation&&surface.deformation->skin)throw std::runtime_error("Genuine skin silently lost");}
  if(!primitive.indices||primitive.indices->count!=mesh.indices.size())throw std::runtime_error("Ordered corners lost");for(size_t c=0;c<mesh.indices.size();++c){auto p=mesh.positions[mesh.indices[c]];auto w=world.point({p.x,p.y,p.z});auto actual=consume(node,cgltf_accessor_read_index(primitive.indices,c));auto error=double(length(actual-Vec3{float(w[0]),float(w[1]),float(w[2])}));maximum=std::max(maximum,error);if(error>2e-5)throw std::runtime_error("Independent VRM posed own-IBM corner mismatch");++corners;}
 }
 check(skins==19&&rigid==3&&corners>10000,"Every real skinned and rigid source part is independently evaluated after fitting");
 // Resolve true emitted humanoid identities through the metadata, not names.
 uint32_t oldHead=0,newHead=0;for(const auto&bone:original.at("humanoid").at("humanBones"))if(bone.at("bone").get_ref<const std::string&>()=="head")oldHead=bone.at("node");for(const auto&bone:vrm.at("humanoid").at("humanBones"))if(bone.at("bone").get_ref<const std::string&>()=="head")newHead=bone.at("node");
 const auto prefix=product(node_world(raw->nodes[newHead]),inverse(dmatrix(pose.world[oldHead])));
 auto reference=[&](uint32_t source){return product(product(product(prefix,dmatrix(pose.world[source])),inverse(dmatrix(graph.rest_world[source]))),dmatrix(graph.model->asset->nodes[source].world));};
 check(vrm.at("firstPerson").at("firstPersonBone").get<uint32_t>()==newHead,"First-person root remains the actual humanoid head, never a helper");Vec3 oldOffset{};if(original.at("firstPerson").contains("firstPersonBoneOffset"))oldOffset=unity_point(original.at("firstPerson").at("firstPersonBoneOffset"));near(point(node_world(raw->nodes[newHead]),unity_point(vrm.at("firstPerson").at("firstPersonBoneOffset"))),point(reference(oldHead),oldOffset));check(true,"First-person Unity-to-glTF reflected XYZ point matches independent current pose and original bind frame");
 const auto&oldSpring=original.at("secondaryAnimation"),&newSpring=vrm.at("secondaryAnimation");
 for(size_t i=0;i<oldSpring.at("colliderGroups").size();++i){auto old=oldSpring.at("colliderGroups").at(i),now=newSpring.at("colliderGroups").at(i);near(node_world(raw->nodes[now.at("node").get<size_t>()]),reference(old.at("node")));old.erase("node");now.erase("node");check(old==now,"Collider offsets/radii/parameters stay byte/value exact under an independently checked attachment basis");}
 for(size_t i=0;i<oldSpring.at("boneGroups").size();++i){const auto&old=oldSpring.at("boneGroups").at(i),&now=newSpring.at("boneGroups").at(i);if(old.contains("center")&&old.at("center").get<int>()>=0){near(node_world(raw->nodes[now.at("center").get<size_t>()]),reference(old.at("center")));check(true,"Spring center retains the original bind-following world basis");}
  auto visit=[&](auto&&self,uint32_t source,size_t emitted,size_t depth)->void{if(depth>256)throw std::runtime_error("Unexpected spring cycle");const auto&children=graph.model->asset->nodes[source].children;const auto&node=raw->nodes[emitted];if(node.children_count!=children.size())throw std::runtime_error("Spring acquired helper/render children");for(size_t c=0;c<children.size();++c){auto actual=dmatrix(graph.model->asset->nodes[children[c]].local);float local[16];cgltf_node_transform_local(node.children[c],local);for(size_t k=0;k<16;++k)if(std::abs(local[k]-actual[k])>2e-6)throw std::runtime_error("Spring authored first-child ordering/transform changed");self(self,children[c],size_t(node.children[c]-raw->nodes),depth+1);}};
  for(size_t r=0;r<old.at("bones").size();++r)visit(visit,old.at("bones").at(r),now.at("bones").at(r),0);check(true,"All recursively simulated children and first-child tails retain exact authored topology/order");
 }
 check(scene.encode()==before,"Fitted VRM export preserves native source, own paint, material, morph and first rig sources");std::cout<<file.filename().string()<<" corners="<<corners<<" world_max="<<maximum<<'\n';
}
}
int main(int argc,char**argv)try{
 if(argc!=4)return 2;auto dir=std::filesystem::path(argv[3]);std::filesystem::create_directories(dir);
 for(size_t model=1;model<=2;++model){auto placed=dir/(std::to_string(model)+"-source-placed.vrm"),input=dir/(std::to_string(model)+"-source-rigid.vrm");vrm_source_fixture::source_variant(argv[model],placed,2);vrm_source_fixture::with_rigid_accessories(placed,input);ImportAuthoringOptions options;options.paint_resolution=64;auto prepared=prepare_authoring_import(Scene{},input,options);auto scene=prepared.scene;const auto selected=prepared.objects.front();const auto head=scene.object(selected).deformation->humanoid->joints.at("head");RigRestJointEdit fit;fit.joint=head;auto world=(scene.world_matrix(selected)*AffineTransform(scene.object(selected).deformation->skeleton->world()[head])).point({0,0,0});fit.world_position=Vec3{float(world[0]+.005),float(world[1]-.002),float(world[2]+.001)};author_rig_rest(scene,selected,{&fit,1});verify_vrm(scene,selected,dir/(std::to_string(model)+"-fitted.vrm"));RigEdit pose;pose.joint=JointAdjustment{head,{0,11,0},{.001f,0,0}};edit_rig(scene,selected,pose);verify_vrm(scene,selected,dir/(std::to_string(model)+"-posed.vrm"));auto file=dir/(std::to_string(model)+"-restart.dsculpt");scene.save(file);auto restart=Scene::load(file);check(restart.encode()==scene.encode(),"Actual fitted source VRM survives complete native restart before export");verify_vrm(restart,selected,dir/(std::to_string(model)+"-restart.vrm"));
 }
 std::cout<<checks<<" independent actual fitted VRM checks passed\n";return 0;
}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}
